  "codebook": {
    "clarification": "Include as credit-claiming: (1) announcements that federal money, grants, projects, military missions, disaster declarations, designations, or appointments are flowing to the senator's state or constituents, even without an explicit 'I secured,' because announcing the benefit associates the senator with its delivery; (2) explicit claims of responsibility such as 'I helped secure,' 'my amendment,' 'legislation I authored,' 'at my request,' or 'I played a key role' in a specific delivered outcome; (3) claims that the senator's amendment or provision was adopted, that their negotiated language was included in legislation, or that their bill passed at any stage; (4) claims that the senator's advocacy, letters, or oversight produced concrete results (e.g., an agency decision following their request, funds recouped through their investigation); and (5) substantive passages touting the senator's record of delivered benefits or enacted legislation benefiting a constituency, even when packaged with a new proposal or event.",
    "definition": "Credit-claiming occurs when a senator uses a press release to assert personal or shared responsibility for a concrete governmental benefit or outcome that has been delivered, secured, enacted, or formally approved—such as federal funds, grants, projects, designations, appointments, or adopted legislative provisions—or for results produced by the senator's own advocacy or oversight, thereby presenting themselves as someone who delivers benefits for their state or a constituency.",
    "negative_clarification": "Do NOT classify as credit-claiming: statements of issue positions or explanations of votes; advocacy, urging, or demands regarding pending proposals with no delivered result (including merely introducing or cosponsoring a bill); criticism of the administration or opponents; condolences, tributes, and remembrances; announcements of town meetings, hearings, or markups; ceremonies honoring other people; general biographical references (committee seats, 'played a key role in the debate,' lists of priorities or past support) that do not assert responsibility for a specific delivered benefit; merely applauding, welcoming, or commenting on another actor's decision without claiming a causal role; and references to one's past legislative work made in service of criticizing non-implementation rather than advertising a delivered benefit.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Kerry's statement is entirely a critique of the Bush administration's port security failures. It takes a position and assigns blame but claims no benefit or outcome that Kerry himself produced."
      },
      {
        "document_id": "918",
        "explanation": "Allard's release merely announces a town meeting and lists his committee assignments. It is an event notice and general biography with no assertion of responsibility for any delivered benefit."
      },
      {
        "document_id": "3659",
        "explanation": "Clinton 'welcomes' an advisory board recommendation that is not yet a final decision, urges the Secretary to act, and pledges to keep pressing. She neither announces a delivered benefit nor claims a causal role in the recommendation—this is advocacy, not credit-claiming."
      }
    ],
    "positive_examples": [
      {
        "document_id": "2627",
        "explanation": "Talent explicitly announces that 'the Senate has approved his request for $1.5 million' for a University of Missouri facility—a direct claim that he secured federal funds for his state."
      },
      {
        "document_id": "4508",
        "explanation": "Lott announces FEMA trailers being moved to Mississippi and explicitly notes the move 'follows the Senator's Monday appeal to President Bush'—claiming his personal intervention produced a delivered benefit."
      },
      {
        "document_id": "4771",
        "explanation": "Clinton states she 'played a key role... in preventing the removal of four C-130 aircraft' from Stratton—claiming responsibility for a specific delivered outcome protecting a New York installation."
      }
    ]
  }
